research::Configuration ResearchExplorer::configuration()const{
    research::Configuration c;c.mode=static_cast<research::Mode>(m_mode->currentIndex());c.gamma=m_gamma->value();c.t0=m_t0->value();c.t1=m_t1->value();c.sampleStep=m_step->value();bool rtol=false,atol=false;c.rtol=m_rtol->text().toDouble(&rtol);c.atol=m_atol->text().toDouble(&atol);if(!rtol||!atol)throw research::ScriptError("Enter numeric solver tolerances, for example 1e-8 and 1e-10.");c.maximumSeconds=m_seconds->value();c.method=m_method->currentText().toStdString();c.transient=m_transient->value();c.qrStep=m_qr->value();c.threads=m_threads->value();c.maximumIterations=m_iterations->value();
    for(int row=0;row<m_states->rowCount();++row)c.states.push_back({cell(m_states,row,0).toStdString(),cell(m_states,row,1).toStdString(),cell(m_states,row,2).toStdString(),cell(m_states,row,3).toStdString()});
    for(int row=0;row<m_parameters->rowCount();++row)c.parameters.push_back({cell(m_parameters,row,0).toStdString(),cell(m_parameters,row,1).toStdString(),cell(m_parameters,row,2).toStdString()});
    for(int row=0;row<m_sweeps->rowCount();++row){bool lower=false,upper=false,count=false;const auto low=cell(m_sweeps,row,1).toDouble(&lower),high=cell(m_sweeps,row,2).toDouble(&upper);const auto samples=cell(m_sweeps,row,3).toInt(&count);if(!lower||!upper||!count)throw research::ScriptError("Simultaneous ranges need numeric lower/upper bounds and integer sample counts.");c.sweeps.push_back({cell(m_sweeps,row,0).toStdString(),low,high,samples});}
    for(int row=0;row<m_algebras->rowCount();++row)c.algebras.push_back({cell(m_algebras,row,0).toStdString(),cell(m_algebras,row,1).toStdString()});
    c.fitType=m_fitType->currentText().toStdString();c.fitMethod=m_fitMethod->currentText().toStdString();c.fitExpression=m_fitExpression->text().toStdString();c.xData=m_xdata->text().toStdString();c.yData=m_ydata->text().toStdString();c.sweepParameter=m_sweep->text().trimmed().toStdString();c.sweepLower=m_lower->value();c.sweepUpper=m_upper->value();c.sweepSamples=m_samples->value();c.maximumRuns=m_maxRuns->value();c.initialRows=m_initialRows->toPlainText().trimmed().toStdString();c.checkpoint=m_checkpoint->text().toStdString();c.resume=m_resume->isChecked();c.overwriteCheckpoint=m_overwrite->isChecked();c.spatial=m_spatial->configuration();c.livePlots=m_livePlots->isChecked();return c;
}
void ResearchExplorer::setConfiguration(const research::Configuration& c){
    m_loading=true;m_mode->setCurrentIndex(static_cast<int>(c.mode));m_gamma->setValue(c.gamma);m_t0->setValue(c.t0);m_t1->setValue(c.t1);m_step->setValue(c.sampleStep);m_rtol->setText(real(c.rtol));m_atol->setText(real(c.atol));m_seconds->setValue(c.maximumSeconds);m_method->setCurrentText(QString::fromStdString(c.method));m_threads->setValue(c.threads);m_transient->setValue(c.transient);m_qr->setValue(c.qrStep);m_iterations->setValue(c.maximumIterations);m_states->setRowCount(static_cast<int>(c.states.size()));for(std::size_t row=0;row<c.states.size();++row){const auto& s=c.states[row];const std::array<std::string,4> values{s.type,s.name,s.initial,s.rhs};for(int col=0;col<4;++col)m_states->setItem(static_cast<int>(row),col,new QTableWidgetItem(QString::fromStdString(values[static_cast<std::size_t>(col)])));}m_parameters->setRowCount(static_cast<int>(c.parameters.size()));for(std::size_t row=0;row<c.parameters.size();++row){const auto& p=c.parameters[row];const std::array<std::string,3> values{p.type,p.name,p.value};for(int col=0;col<3;++col)m_parameters->setItem(static_cast<int>(row),col,new QTableWidgetItem(QString::fromStdString(values[static_cast<std::size_t>(col)])));}
    m_fitType->setCurrentText(QString::fromStdString(c.fitType));m_fitExpression->setText(QString::fromStdString(c.fitExpression));m_fitMethod->setCurrentText(QString::fromStdString(c.fitMethod));m_xdata->setText(QString::fromStdString(c.xData));m_ydata->setText(QString::fromStdString(c.yData));m_sweep->setText(QString::fromStdString(c.sweepParameter));m_lower->setValue(c.sweepLower);m_upper->setValue(c.sweepUpper);m_samples->setValue(c.sweepSamples);m_maxRuns->setValue(c.maximumRuns);m_initialRows->setPlainText(QString::fromStdString(c.initialRows));m_checkpoint->setText(QString::fromStdString(c.checkpoint));m_resume->setChecked(c.resume);m_overwrite->setChecked(c.overwriteCheckpoint);
    m_algebras->setRowCount(static_cast<int>(c.algebras.size()));for(std::size_t row=0;row<c.algebras.size();++row){m_algebras->setItem(static_cast<int>(row),0,new QTableWidgetItem(QString::fromStdString(c.algebras[row].name)));m_algebras->setItem(static_cast<int>(row),1,new QTableWidgetItem(QString::fromStdString(c.algebras[row].preset)));}
    m_livePlots->setChecked(c.livePlots);m_livePlots->setEnabled(c.mode==research::Mode::Ode||c.mode==research::Mode::Chaos||c.mode==research::Mode::Discovery||(c.mode==research::Mode::Pde&&c.spatial.pde.integrator=="implicit"));
    m_sweeps->setRowCount(static_cast<int>(c.sweeps.size()));for(std::size_t row=0;row<c.sweeps.size();++row){const auto& sweep=c.sweeps[row];const QStringList values{QString::fromStdString(sweep.parameter),real(sweep.lower),real(sweep.upper),QString::number(sweep.samples)};for(int column=0;column<4;++column)m_sweeps->setItem(static_cast<int>(row),column,new QTableWidgetItem(values[column]));}m_sweeps->setEnabled(c.mode==research::Mode::Discovery);
    m_spatial->setConfiguration(c.spatial);m_spatial->setMode(c.mode);const bool spatial=c.mode==research::Mode::Pde||c.mode==research::Mode::Geometry||c.mode==research::Mode::Mechanics;
    m_inputTabs->setTabVisible(2,!spatial);m_inputTabs->setTabVisible(3,spatial);m_states->setEnabled(!spatial);for(const auto* name:{"researchAddState","researchRemoveState"})if(auto* button=findChild<QPushButton*>(name))button->setEnabled(!spatial);
    m_method->setEnabled(!spatial);m_rtol->setEnabled(!spatial||(c.mode==research::Mode::Pde&&c.spatial.pde.integrator=="implicit")||(c.mode==research::Mode::Mechanics&&c.spatial.mechanics.form=="constrained"));m_atol->setEnabled(m_rtol->isEnabled());const bool geometry=c.mode==research::Mode::Geometry;for(auto* value:{m_t0,m_t1,m_step,m_seconds})value->setEnabled(!geometry);m_threads->setEnabled(c.mode!=research::Mode::Mechanics);m_iterations->setEnabled(c.mode==research::Mode::Fitting);m_transient->setEnabled(c.mode==research::Mode::Chaos);m_qr->setEnabled(c.mode==research::Mode::Chaos);if(spatial)m_inputTabs->setCurrentWidget(m_spatial);
    m_loading=false;refreshParameterSlider();m_preview->clear();markChanged();
}
QString ResearchExplorer::generatedScript(QString* error,bool preflight)const{if(error)error->clear();try{return QString::fromStdString(research::generateScript(configuration(),preflight));}catch(const std::exception& e){if(error)*error=QString::fromUtf8(e.what());return {};}}
void ResearchExplorer::refreshParameterSlider(bool rebuild){
    if(m_loading)return;
    const QSignalBlocker comboBlock(m_sliderParameter),sliderBlock(m_parameterSlider);
    int row=m_sliderParameter->currentIndex();
    if(rebuild){const int selected=m_parameters->currentRow();if(selected>=0)row=selected;m_sliderParameter->clear();for(int n=0;n<m_parameters->rowCount();++n)m_sliderParameter->addItem(cell(m_parameters,n,1));if(row<0||row>=m_parameters->rowCount())row=m_parameters->rowCount()?0:-1;m_sliderParameter->setCurrentIndex(row);}
    const double low=m_sliderLow->value(),high=m_sliderHigh->value();
    bool okay=false;double number=0;
    static const QRegularExpression literal(QStringLiteral("^[+-]?(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)(?:[eE][+-]?[0-9]+)?$"));
    QString reason;
    if(row<0||row>=m_parameters->rowCount())reason=tr("Add and select an existing real parameter to enable its slider.");
    else if(cell(m_parameters,row,0)!="real")reason=tr("Only real parameters have a scalar slider; Pentarnion values stay in the parameter table.");
    else if(!literal.match(cell(m_parameters,row,2)).hasMatch())reason=tr("The selected value is an expression. Enter a finite real numeric literal to enable its slider.");
    else{number=cell(m_parameters,row,2).toDouble(&okay);if(!okay||!std::isfinite(number))reason=tr("The selected real literal must be finite.");else if(!std::isfinite(low)||!std::isfinite(high)||low>=high)reason=tr("Slider minimum must be strictly smaller than its maximum.");else if(number<low||number>high)reason=tr("The current literal is outside this slider range; edit the range or the table value explicitly.");}
    const bool enabled=reason.isEmpty();m_parameterSlider->setEnabled(enabled);m_sliderParameter->setEnabled(m_parameters->rowCount()>0);
    if(enabled){const double fraction=(number-low)/(high-low);m_parameterSlider->setValue(static_cast<int>(std::lround(fraction*m_parameterSlider->maximum())));m_sliderHint->setText(tr("%1 = %2. Moving the slider changes the checked source only; choose Run / Recompute explicitly.").arg(cell(m_parameters,row,1),real(number)));}
    else m_sliderHint->setText(reason);
    m_parameterSlider->setToolTip(m_sliderHint->text());
}
void ResearchExplorer::markChanged(){if(m_loading)return;m_fresh=false;updateButtons();m_status->setText(m_busy?tr("Running the submitted snapshot. Current controls changed; its result will be labelled stale."):tr("Controls changed. Generate a checked script or choose Run / Recompute; no model was executed."));}
void ResearchExplorer::updateButtons(){m_run->setEnabled(!m_busy);m_cancel->setEnabled(m_busy);m_preflight->setEnabled(!m_busy&&(m_mode->currentIndex()==static_cast<int>(research::Mode::Discovery)||m_mode->currentIndex()>=static_cast<int>(research::Mode::Pde)));m_export->setEnabled(!m_busy&&m_fresh);const bool discovery=m_fresh&&m_completed.mode==research::Mode::Discovery;m_replayButton->setEnabled(!m_busy&&discovery);m_filterButton->setEnabled(!m_busy&&discovery);}
void ResearchExplorer::setExecutionBusy(bool busy){m_busy=busy;updateButtons();if(busy)m_status->setText(m_pendingHash.isEmpty()?tr("The shared execution worker is busy. Controls remain editable; Run waits for completion."):tr("Running submitted snapshot %1. Cancel uses Studio's shared worker.").arg(m_pendingHash.left(12)));}
void ResearchExplorer::submit(bool preflight){if(m_busy)return;QString error;const auto source=generatedScript(&error,preflight);if(source.isEmpty()){m_status->setText(error);return;}m_submitted=configuration();m_pendingPreflight=preflight;m_pendingHash=hash(source);m_pendingSource=source;m_fresh=false;m_preview->setPlainText(source);m_status->setText(tr("Submitted checked snapshot %1. See the shared Command Window and figures.").arg(m_pendingHash.left(12)));updateButtons();emit runRequested(source);}
void ResearchExplorer::submissionRejected(const QString& message){m_pendingHash.clear();m_pendingAuxHash.clear();m_busy=false;m_fresh=false;updateButtons();m_status->setText(message);}
void ResearchExplorer::acceptResult(const runtime::ExecutionResult& result){
    const auto sourceHash=QString::fromStdString(result.sourceHash);const bool primary=!m_pendingHash.isEmpty()&&sourceHash==m_pendingHash,auxiliary=!m_pendingAuxHash.isEmpty()&&sourceHash==m_pendingAuxHash;
    if(!primary&&!auxiliary){m_fresh=false;updateButtons();return;}QStringList output;for(const auto& line:result.output)output<<QString::fromStdString(line);for(const auto& d:result.runtimeDiagnostics)output<<QString::fromStdString(d.code+": "+d.message);m_results->setPlainText(output.join('\n').left(65536));
    if(primary){m_completed=m_submitted;m_completedSource=m_pendingSource;m_completedHash=m_pendingHash;m_completedSymbols=result.analysis.symbols;m_pendingHash.clear();QString error;const auto current=generatedScript(&error,m_pendingPreflight);m_fresh=result.ok()&&!m_pendingPreflight&&!current.isEmpty()&&hash(current)==m_completedHash;for(const auto& variable:result.variables)if(variable.name=="research_runs"){bool okay=false;const auto count=QString::fromStdString(variable.value).toInt(&okay);if(okay&&count>=1&&count<=4096)m_replay->setMaximum(count);}}
    else{m_pendingAuxHash.clear();if(!result.ok())m_fresh=false;}
    const auto status=result.status==runtime::ExecutionStatus::Cancelled?tr("Cancelled; completed checkpoints remain available."):!result.ok()?tr("Execution failed; inspect the shared diagnostics."):m_pendingPreflight&&primary?tr("Preflight completed without running the ensemble."):m_fresh?tr("Completed snapshot %1. Export/replay uses these accepted settings.").arg(m_completedHash.left(12)):tr("Completed an older settings snapshot. Recompute before exporting current controls.");m_status->setText(status);updateButtons();
}
QString ResearchExplorer::checkedAux(const QString& command,QString* error)const{if(error)error->clear();if(!m_fresh||m_busy){if(error)*error=tr("Run the current settings and wait for completion before export/filter/replay.");return {};}language::AnalysisOptions options;options.gamma=m_completed.gamma;options.initialSymbols=m_completedSymbols;const auto analysis=language::analyse(command.toStdString(),options);if(!analysis.ok()){if(error)for(const auto& d:analysis.diagnostics)if(d.severity==language::Severity::Error){*error=QString::fromStdString(d.code+": "+d.message);break;}return {};}return command;}
QString ResearchExplorer::exportCommand(const QString& path,QString* error)const{
    if(path.isEmpty()||path.contains(QChar::Null)){if(error)*error=tr("Choose a nonempty data filename.");return {};}QString values;
    if(m_completed.mode==research::Mode::Ode){
        QStringList columns{"research_solution.t"};language::AnalysisOptions types;types.gamma=m_completed.gamma;(void)research::prepareAlgebras(m_completed,types);
        for(const auto& state:m_completed.states){const auto typed=research::numericControlType(state.type,types);const auto width=language::coordinateWidth(typed.type,typed.schema);const auto member="research_solution."+QString::fromStdString(state.name);const bool array=typed.type==language::Type::RealMatrix||typed.type==language::Type::PentarnionMatrix||typed.type==language::Type::ElementMatrix;
            if(width==1&&!array)columns<<member;else for(std::size_t k=0;k<width;++k)columns<<QStringLiteral("%1(%2,%3)").arg(array?"statecoord":"coeff",member).arg(k);
        }
        for(auto& column:columns)column=QStringLiteral("reshape(%1,[],1)").arg(column);
        values="["+columns.join(',')+"]";
    }
    else if(m_completed.mode==research::Mode::Pde&&m_completed.spatial.pde.integrator=="implicit")values="[research_result.t,research_result.values]";
    else if(m_completed.mode==research::Mode::Pde){QStringList columns{"research_result.t"};const int width=m_completed.spatial.pde.valueType=="pentarnion"?5:1;for(int c=0;c<width;++c)columns<<QStringLiteral("pdecoeff(research_result,%1)").arg(c);values="["+columns.join(',')+"]";}
    else if(m_completed.mode==research::Mode::Geometry)values="research_mesh.vertices";
    else if(m_completed.mode==research::Mode::Mechanics)values=m_completed.spatial.mechanics.form=="constrained"?"[research_result.t,research_result.q,research_result.v,research_result.lambda,research_result.energy]":"[research_result.t,research_result.q,research_result.v,research_result.p]";
    else if(m_completed.mode==research::Mode::Chaos)values="[research_result.t,research_result.history]";else if(m_completed.mode==research::Mode::Fitting)values="[research_result.xdata,research_result.observations,research_result.fitted]";else values="[research_ids,research_result.status_codes,research_result.maximum_norm,research_result.states]";
    return checkedAux(QStringLiteral("writematrix(%1,%2);\n").arg(values,QString::fromStdString(research::quote(path.toStdString()))),error);
}
QString ResearchExplorer::replayCommand(QString* error)const{if(m_completed.mode!=research::Mode::Discovery){if(error)*error=tr("Replay requires a completed discovery experiment.");return {};}return checkedAux(QStringLiteral("clear research_replay;record research_replay=experimentrun(research_model,research_result,%1);display(research_replay);figure(61,\"Name\",\"Research Explorer: selected replay\",\"NumberTitle\",\"off\");clf;plot(research_replay.t,research_replay.values(:,1));title(\"Selected run: coordinate 1; full replay retained\");\n").arg(m_replay->value()),error);}
void ResearchExplorer::submitAux(const QString& command){m_pendingAuxHash=hash(command);m_status->setText(tr("Submitted an explicit export/filter/replay command for the completed snapshot."));emit exportRequested(command);}
bool ResearchExplorer::saveScript(const QString& path,QString* error,bool overwrite,const QByteArray& expectedDiskHash)const{
    if(error)error->clear();
    const auto source=generatedScript(error);if(source.isEmpty())return false;
    auto reject=[&](const QString& message){if(error)*error=message;return false;};const bool exists=QFileInfo::exists(path);
    if(exists&&(!overwrite||expectedDiskHash.size()!=32||diskHash(path)!=expectedDiskHash))return reject(tr("Existing source was not changed. Choose a fresh filename or confirm overwrite of the unchanged file."));
    QSaveFile file(path);file.setDirectWriteFallback(false);const auto bytes=source.toUtf8();if(!file.open(QIODevice::WriteOnly)||file.write(bytes)!=bytes.size())return reject(file.errorString());
    if(QFileInfo::exists(path)!=exists||(exists&&diskHash(path)!=expectedDiskHash)){file.cancelWriting();return reject(tr("Source changed externally before saving; the original file was preserved."));}
    if(!file.commit())return reject(file.errorString());
    return true;
}

bool ResearchExplorer::importDataFile(const QString& path,QString* error){
    if(error)error->clear();
    try{runtime::dataio::Options limits;limits.maxElements=512;limits.maxFileBytes=1024*1024;limits.maxUncompressedBytes=4*1024*1024;const auto table=runtime::dataio::readMatrix(std::filesystem::path(path.toStdWString()),{},limits);if(!table.rows||table.columns<2)throw research::ScriptError("Fitting data needs one x column and at least one y column.");auto literal=[&](std::size_t begin,std::size_t end){QString text="[";for(std::size_t row=0;row<table.rows;++row){if(row)text+=';';for(std::size_t column=begin;column<end;++column){if(column>begin)text+=',';text+=real(table.values[row*table.columns+column]);}}return text+']';};const auto x=literal(0,1),y=literal(1,table.columns);if(x.size()>4096||y.size()>4096)throw research::ScriptError("Imported data exceeds the editable4096-character control allowance.");m_xdata->setText(x);m_ydata->setText(y);return true;}catch(const std::exception& failure){if(error)*error=QString::fromUtf8(failure.what());return false;}
}

